pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != address(c.bank()));
        vm.deal(caller, 10 wei);

        uint bankBalanceBefore = address(c.bank()).balance;

        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 wei}(abi.encodeWithSignature("play()"));

        if (success) {
            uint bankBalanceAfter = address(c.bank()).balance;
            assertTrue(bankBalanceAfter == bankBalanceBefore + 1 wei, "Bank did not receive exactly 1 wei after a successful play");
        } else {
            // If play reverts (e.g., caller is bank), no change expected
            assertTrue(true);
        }
    }
}

