pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player) public {
        vm.assume(player != address(c) && player != address(0) && player != c.bank());

        uint initialPot = c.pot();

        vm.deal(player, 10 wei);
        vm.prank(player);
        (bool success, ) = address(c).call{value: 10 wei}(abi.encodeWithSignature("play()"));

        uint finalPot = c.pot();

        // After a successful play, either pot is 0 (random == 0) or unchanged (random != 0)
        assertTrue(!success || finalPot == 0 || finalPot == initialPot + 10 wei);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player) public {
        vm.assume(player != address(this) && player != address(c));
        vm.deal(player, 10 ether);

        // Record initial state
        uint initialPot = c.pot();

        // Play the game
        vm.prank(player);
        (bool success, ) = address(c).call{value: 10 wei}(abi.encodeWithSignature("play()"));

        // Check the rule: If the call succeeded, then either pot becomes 0 (when random == 0)
        // or pot increases by exactly 10 (the ticket amount) when the condition fails
        uint finalPot = c.pot();
        bool ruleHolds;
        if (success) {
            // In the correct version, either pot is reset to 0 (win) or increased by 10 (loss)
            // This property is broken by the mutant where random is always 0, so pot is always 0
            ruleHolds = (finalPot == 0) || (finalPot == initialPot + 10 wei);
        } else {
            // If call reverts, no state change
            ruleHolds = finalPot == initialPot;
        }
        assertTrue(ruleHolds);
    }
}

