import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender) public {
        vm.assume(sender != address(c));
        vm.deal(sender, 10 ether);

        uint bankBefore = address(c.bank()).balance;
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));

        if (ok) {
            uint bankAfter = address(c.bank()).balance;
            assertTrue(bankAfter >= bankBefore);
        }
    }
}
